"""Write streets.js (the STREETS global used by app.js) from tools/data/streets.json.

Usage: python tools/build_streets_js.py tools/data/streets.json streets.js
"""
import sys

src, out = sys.argv[1], sys.argv[2]
data = open(src, encoding="utf-8").read().strip()
open(out, "w", encoding="utf-8", newline="\n").write(
    "/* Street geometry for the mini maps: © OpenStreetMap contributors (ODbL), simplified.\n"
    "   Generated by tools/build_streets_js.py — do not edit by hand. */\n"
    f"var STREETS = {data};\n")
print("wrote", out, len(data), "chars")
